/* Team logos, one per owner, inlined as data URIs.

   Inlined rather than loaded as ten separate files for one reason that matters:
   the trophy room paints these onto canvases and hands the result to WebGL as a
   texture. An <img> pointing at an external file taints the canvas under
   file://, and a tainted canvas throws on upload — so the hall would go black
   for anyone opening the site straight off disk. A data URI is same-origin
   everywhere. It also saves ten requests.

   Keyed by owner id, because a manager keeps their logo when the team name
   changes. Most are vector; a raster is taken where that is the artwork that
   exists. Regenerate with tools/build-logos.mjs after replacing a file in
   logos/. Plain script, not a module, so it works from file:// like
   league-data.js. */

const TEAM_LOGOS = {
  ted_williams: "data:image/svg+xml;base64,",
  charlie_vonderheid: "data:image/svg+xml;base64,",
  niko_nadreau: "data:image/webp;base64,",
  jp_torack: "data:image/svg+xml;base64,",
  ian_farroll: "data:image/svg+xml;base64,",
  matt_windler: "data:image/svg+xml;base64,",
  nathan_rich: "data:image/svg+xml;base64,",
  matthew_kluba: "data:image/svg+xml;base64,",
  grant_thornberry: "data:image/svg+xml;base64,",
  jared_thornberry: "data:image/svg+xml;base64,"
};

window.TEAM_LOGOS = TEAM_LOGOS;
